import type { Metadata } from "next"
import { getSession } from "@/lib/auth"
import BrandBook from "@/lib/visual/brand-book.generated"
import RefreshWhenSignedIn from "./RefreshWhenSignedIn"

// The brand book is generated by 434-context `04 Build/build_visual_tokens.py`
// with the design tokens; this route only serves it. Admin only, for signed-in
// 434 staff (founder, 2026-10-24).
//
// The admin layout's sign-in gate runs in the browser, and a server component
// passed to it is still sent to the browser. So the session is checked here,
// on the server, and the book is rendered only for staff. Interns are the
// self-registered cohort, not staff.
export const metadata: Metadata = {
  title: "Brand book | 434 MEDIA",
  robots: { index: false, follow: false },
}

export default async function BrandBookPage() {
  const session = await getSession()
  if (!session) return <RefreshWhenSignedIn />
  if (session.role === "intern") {
    return <p className="t-body p-8">The brand book is available to 434 staff only.</p>
  }
  return <BrandBook />
}
